type PointerPress = Pick<PointerEvent,'button'|'isPrimary'|'preventDefault'>;
type KeyPress = Pick<KeyboardEvent,'code'|'repeat'|'preventDefault'>;
type Click = Pick<MouseEvent,'detail'>;

/** Jump on the start of a press, not the later click generated by its release. */
export function createJumpInput(activate:()=>void){
 return {
  pointerDown(event:PointerPress){
   if(event.button!==0||!event.isPrimary)return;
   event.preventDefault();
   activate();
  },
  keyDown(event:KeyPress){
   if(event.code!=='Space'&&event.code!=='Enter')return;
   // Cancels the native keyup/click activation; each physical press jumps once.
   event.preventDefault();
   if(!event.repeat)activate();
  },
  click(event:Click){
   // Screen readers and programmatic button activation can provide a click only.
   // A pointer click has detail > 0 and was already handled on pointerdown.
   if(event.detail===0)activate();
  }
 };
}
